mapper.select:
select  from ai_chat_message
 where run_id = #{runId} and message_kind = #{messageKind}
 order by message_id desc limit 1

select  from ai_chat_message
 where conversation_id = #{conversationId}
   and visible_to_llm = '0'
   and message_type <> 'SUMMARY'
   and message_id > #{fromId}
 order by message_id asc

select  from ai_chat_message
 where run_id = #{runId}
 order by message_id asc


select ifnull(sum(tokens), 0) from ai_chat_message
 where conversation_id = #{conversationId}
   and message_id > #{lastSummaryId}
   and visible_to_llm = '0'

select ifnull(sum(tokens), 0) from ai_chat_message
 where conversation_id = #{conversationId}
   and message_id > #{lastSummaryId}
   and visible_to_llm = '0'
   and (message_type = 'TOOL'
        or (message_type = 'ASSISTANT' and tool_calls is not null))

select  from ai_chat_message
 where session_id = #{sessionId}
 order by message_id asc

select  from ai_chat_message
 where session_id = #{sessionId}

   and message_id < #{beforeMessageId}

 order by message_id desc
 limit #{limit}

select  from ai_chat_message
 where session_id = #{sessionId}
   and message_type = 'USER'
   and message_id < #{firstMessageId}

   and message_id < #{beforeMessageId}

 order by message_id desc
 limit 1

select  from ai_chat_message
 where session_id = #{sessionId}
   and message_id >= #{fromMessageId}

   and message_id < #{toMessageId}

 order by message_id asc

select count(1) from ai_chat_message
 where session_id = #{sessionId}
   and message_id < #{messageId}

select tool_result_path from ai_chat_message
 where conversation_id = #{conversationId}
   and message_id >= #{fromId}
   and tool_result_path is not null
   and tool_result_path != ''


select message_id from ai_chat_message
 where conversation_id = #{conversationId}
   and message_id >= #{fromId}
 order by message_id asc

mapper.delete:

delete from ai_chat_message
 where conversation_id = #{conversationId}
   and message_id >= #{fromId}

mapper.update:
update ai_chat_message
   set prompt_tokens = #{promptTokens},
       completion_tokens = #{completionTokens},
       model_name = #{modelName},
       usage_source = #{usageSource}
 where message_id = #{messageId}

mapper.select:
select  from ai_chat_message
 where conversation_id = #{conversationId}
   and tool_call_id = #{toolCallId}
 limit 1

mapper.update:
update ai_chat_message
   set pruned = '1', tokens = #{tokens}
 where conversation_id = #{conversationId}
   and tool_call_id = #{toolCallId}
